    "id": 5,
    "slug": "nih-researchers-identify-regulatory-cells-that-shield-against-inflammatory-bowel-disease",
    "cat": "Biologia",
    "catCls": "biologia",
    "img": "https://www.nih.gov/sites/default/files/styles/max_650x650/public/2026-06/20260608-digestive.jpg?itok=MWu8HEig",
    "inline_images": [],
